/** Replaced at build time (see `vite.config.ts`). */
declare const __VIGIL_VERSION__: string;
/** Git commit the build was made from, or `unknown`. */
declare const __VIGIL_COMMIT__: string;
declare const __VIGIL_BUILD__: "hosted" | "ghpages" | "offline";
/** URL of the Vigil RPC proxy this build uses on mainnet, or `""` (see `vite.config.ts`). */
declare const __VIGIL_PROXY_URL__: string;
